import { Table, GuidColumn, ChoiceColumn, DomainIdColumn } from '../../db'

export const analytics_visualization = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_sync: true,
    },
    audit: true,
    extends: 'par_component',
    extensible: true,
    label: 'Analytics Visualization',
    name: 'analytics_visualization',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        type: ChoiceColumn({
            attributes: {
                choice_script: 'new VisualizationChoiceTypes().get()',
                is_searchable_choice: true,
            },
            script: 'new VisualizationChoiceTypes().get()',
            dropdown: 'dropdown_without_none',
            label: 'Type',
        }),
        sys_domain_path: DomainIdColumn({
            default: 'global',
            label: 'Domain Path',
        }),
    },
    textIndex: true,
})
